main.encounter:
process-module "temple/surface-process-module/1"

process app.page:
  let request = $eventInput
  call northRiver.page

process app.command:
  let request = $eventInput
  call northRiver.command

process northRiver.page:
  let rows = or($request.state.submissions, list())
  let actor = $request.actor
  let employee = eq($actor.role, "employee")
  let manager = eq($actor.role, "manager")
  let visible = if($employee, filter($rows, "row", eq($row.employee, $actor.id)), $rows)
  let lines = map($visible, "row", concat($row.id, " · ", $row.description, " · ", $row.status))
  let forms = list()
  when $employee:
    let forms = list({ command = "submit"; label = "Submit request"; fields = list(
      { name = "id"; label = "Request reference" },
      { name = "description"; label = "Request details" }
    ) })
  when $manager:
    let forms = map(filter($rows, "row", eq($row.status, "Pending")), "row",
      { command = "approve"; label = concat("Approve ", $row.id); fields = list(
        { name = "id"; label = "Request reference"; value = $row.id }
      ) })
  let result = { title = "North River requests"; lines = if(count($lines), $lines, list("No requests yet.")); forms = $forms }

process northRiver.command:
  let rows = or($request.state.submissions, list())
  let actor = $request.actor
  let reference = $request.input.id
  let description = $request.input.description
  let existing = at(filter($rows, "row", eq($row.id, $reference)), 0)
  let result = { error = "This action is unavailable for your app role." }
  when and(eq($actor.role, "employee"), eq($request.command, "submit")):
    let result = { error = "Enter a new request reference and details." }
    when and($reference, $description, not($existing)):
      let submission = { id = $reference; description = $description; employee = $actor.id; status = "Pending" }
      let result = { state = { submissions = append($rows, list($submission)) } }
  when and(eq($actor.role, "manager"), eq($request.command, "approve")):
    let result = { error = "Choose a pending request." }
    when eq(at($existing, "status"), "Pending"):
      let approved = { id = $existing.id; description = $existing.description; employee = $existing.employee;
        manager = $actor.id; status = "Approved" }
      let result = { state = { submissions = map($rows, "row", if(eq($row.id, $reference), $approved, $row)) } }

checks.encounter:
process-module "temple/surface-process-module/1"

process test.approval:
  let request = { state = { }; actor = { id = "employee-test"; role = "employee" }; command = "submit";
    input = { id = "NR-1"; description = "Review a timesheet" } }
  call northRiver.command
  let submitted = $result.state
  let pending = at($submitted.submissions, 0)
  let request = { state = $submitted; actor = { id = "manager-test"; role = "manager" };
    command = "approve"; input = { id = "NR-1" } }
  call northRiver.command
  let approved = at($result.state.submissions, 0)
  let result = and(eq($pending.status, "Pending"), eq($approved.status, "Approved"),
    eq($approved.employee, "employee-test"), eq($approved.manager, "manager-test"))

process test.role-access:
  let request = { state = { submissions = list({ id = "NR-1"; description = "Private request";
    employee = "other-employee"; status = "Pending" }) }; actor = { id = "employee-test"; role = "employee" } }
  call northRiver.page
  let private = eq(at($result.lines, 0), "No requests yet.")
  let request = { state = $request.state; actor = $request.actor; command = "approve"; input = { id = "NR-1" } }
  call northRiver.command
  let result = and($private, not($result.state), eq($result.error, "This action is unavailable for your app role."))
